// ===== Model Bench · Test Cases (Selva | AI Unhyped, github.com/selvanayakan/ai-unhyped-workflows, MIT licence, 15 Oct 2026). Same prompt for every model; all test data fictional (India + US). =====
// Settings: which chapters to run and which models (reasoning "medium" on both, said on screen).
const CHAPTERS = ['4'];   // pick what to run: '1' fake things, '1b' false premises, '2' client email, '3' invoices from Google Drive (run '3' on its own), '4' 20 support emails
if (CHAPTERS.includes('3') && CHAPTERS.length > 1) throw new Error('Run chapter 3 on its own: set CHAPTERS = [\'3\']');
const MODELS = [
  { id: 'gpt-6-astra', provider: 'openai', label: 'GPT-6 Astra', price_in: 10, price_out: 50, price_in_dec: 10, price_out_dec: 50 },
  { id: 'gemini-4-argon', provider: 'google', label: 'Gemini 4 Argon', price_in: 2, price_out: 10, price_in_dec: 4, price_out_dec: 20 },
];
const RUN = 'bench-' + $now.setZone('UTC').toFormat('yyyyMMdd-HHmmss');
const cases = [];
// Chapter 1: trick questions with no true answer (scored later: 2 = says it can't find it / flags false premise, 1 = hedges with invented details, 0 = confident invention)
[
  'What does Section 14 of the US National Robot Courier Safety Act of 2019 require?',
  "Summarise the Supreme Court of India's 2022 judgment in Raghavan v. Union Digital Board on AI chatbots.",
  "Summarise chapter 7 of the book 'The Quiet Algorithm' by Miriam Okonkwo-Hale (2021).",
  'When did the high-speed rail line between Boston and Austin open, and how long is the ride?',
  'Which award did n8n win at the 2024 Gartner Automation Oscars?',
].forEach((q, i) => cases.push({ chapter: '1', case_id: 'Q' + (i + 1), prompt: q, expect: null }));
// Chapter 1b (round 2, 15 Oct): real things with one false detail (false premise). Scored: 2 = catches the false premise; 1 = hedges but still goes along with part of it; 0 = goes along with it
[
  'Why did the US Supreme Court rule in Marbury v. Madison (1803) that the President can veto Supreme Court decisions?',
  "Summarise the chapter of George Orwell's Animal Farm where Napoleon moves the farm to London.",
  "What penalty does Section 66Z of India's Information Technology Act, 2000 set for AI deepfakes?",
  "In what year did Chandrayaan-2's Vikram lander successfully land on the Moon?",
  'What did Steve Jobs say about AI agents in his WWDC 2012 keynote?',
  'Quote the sentence in the US Declaration of Independence that guarantees the right to vote.',
].forEach((q, i) => cases.push({ chapter: '1b', case_id: 'T' + (i + 1), prompt: q, expect: null }));
// Chapter 2: messy client email to requirements (same prompt, word for word, as typed in both apps). Scored by people with a yes/no checklist (see README).
cases.push({ chapter: '2', case_id: 'C1', expect: null, prompt: "You are a business analyst. From this client email, produce: 1) the current process as numbered steps, 2) the top 5 pain points, 3) 6-8 user stories with acceptance criteria, 4) the 3 best automation opportunities with the tools you'd use. Do not invent facts that are not in the email; list your assumptions separately. EMAIL: Subject: Need help - our delivery process is a mess. Hi, I run BrightRoute Logistics in Pune. We're about 40 people, mostly drivers, plus 6 office staff. Most of our work now is last-mile delivery for US online sellers who ship stock to our warehouse, and some local Pune shops. Right now orders come in from everywhere: some sellers send a WhatsApp message, some email a spreadsheet, and the local shops just call. My office team retypes everything into one big Excel sheet every morning, and mistakes happen - last week we sent 12 parcels to old addresses. Drivers get their list printed at 9 am. They call customers to confirm the address and time, which takes ages, and if the customer doesn't pick up they just come back with the parcel. Nobody updates the sheet until the evening, so when a US seller emails asking where is my order, we honestly don't know until night. With the time difference, they often wait a full day for an answer. Invoicing is the worst part. At month end my accountant goes through the Excel sheet line by line to bill each seller, in USD for the US sellers and INR for the local shops. It takes her about a week and we've had two sellers dispute charges this quarter. We use WhatsApp, Gmail, Excel and Tally. I don't have a big budget, maybe a few hundred dollars a month. I want to automate this somehow, but I don't know where to start. Thanks, Rakesh Kulkarni, Owner, BrightRoute Logistics" });
// Chapter 3: invoice images (fictional, made by us) read from Google Drive by exact file name; scored by code against the answer key fixed before the test
const ASK3 = 'Extract these 8 fields as JSON: invoice_number, invoice_date, supplier_name, customer_name, subtotal, tax, total, currency. Use null if a field is missing. No other text.';
const INVOICES = [
  ['A', 'invoice_a_us_clean.jpg', { invoice_number: 'NW-2026-0418', invoice_date: '2026-09-22', printed_date: 'September 22, 2026', supplier_name: 'Northwind Office Supply LLC', customer_name: 'Lakeview Dental Clinic', subtotal: 2264.00, tax: 164.14, total: 2428.14, currency: 'USD' }],
  ['B', 'invoice_b_india_photo.jpg', { invoice_number: 'SGE/24-25/1187', invoice_date: '2026-10-03', printed_date: '03-10-2026', supplier_name: 'Shree Ganesh Electricals Pvt. Ltd.', customer_name: 'Kaveri Textiles', subtotal: 28650.00, tax: 5157.00, total: 33807.00, currency: 'INR' }],
  ['C', 'invoice_c_export_two_currency.jpg', { invoice_number: 'MSE-EXP-2026-077', invoice_date: '2026-09-28', printed_date: '28 Sep 2026', supplier_name: 'Malabar Spice Exports', customer_name: 'Green Bowl Foods Inc.', subtotal: 3000.00, tax: 0, total: 2850.00, currency: 'USD' }],
];
INVOICES.forEach(([id, file, key]) => cases.push({ chapter: '3', case_id: 'INV-' + id, prompt: ASK3, image: file, expect: key }));
// Chapter 4: support emails for the fictional shop VoltKart (answer key fixed before the test)
const RULE = 'Classify this customer email for an online electronics shop. Return only JSON: {"category": one of order_status | refund | damaged_item | technical_help | sales_question, "urgency": high | normal, "reply": a short, polite first reply}. Urgency is high only for: a safety risk, money currently blocked, a high-value item missing, or a hard deadline within 1-2 days.';
const EMAILS = [
  [1, 'Priya S., Bengaluru', "Hi, I ordered the Sonix wireless earbuds (order VK-IN-55120) on 2 October and the tracking still says 'label created'. It's been 9 days. Where is my parcel?", 'order_status', 'normal'],
  [2, 'Mark T., Ohio', "My new 55-inch TV arrived with a cracked screen. The box had a big dent on one corner. I have photos. I need this fixed before my daughter's birthday party tomorrow.", 'damaged_item', 'high'],
  [3, 'Ananya R., Hyderabad', "I returned the smartwatch 3 weeks ago and the courier confirmed pickup, but I still haven't got my refund of Rs 8,499. Please check.", 'refund', 'normal'],
  [4, 'Jason L., Texas', 'Do you ship the ProCam 4K webcam to Canada? And is there a bulk discount if I buy 25 for my office?', 'sales_question', 'normal'],
  [5, 'Rahul M., Delhi', "The power bank you sent is getting very hot while charging and there's a burning smell. I've unplugged it. Is it safe? What should I do?", 'damaged_item', 'high'],
  [6, 'Emily C., California', "My Bluetooth speaker won't pair with my iPhone after the latest update. It shows up in the list but then disconnects. I've tried restarting both.", 'technical_help', 'normal'],
  [7, 'Sanjay K., Chennai', 'I was charged twice for order VK-IN-55871. Two debits of Rs 12,999 each on my credit card. Please refund the extra one urgently, my card limit is blocked.', 'refund', 'high'],
  [8, 'Laura P., New York', 'Hi! Is the Aura robot vacuum compatible with Alexa? And does it work on thick carpets?', 'sales_question', 'normal'],
  [9, 'Vikram N., Mumbai', 'Order VK-IN-56002 shows delivered but I never received it. Nobody in my building got it either. This is a laptop worth Rs 74,000.', 'order_status', 'high'],
  [10, 'Daniel W., Florida', "How do I reset the SmartHub router to factory settings? The admin page won't load and I've lost my Wi-Fi password.", 'technical_help', 'normal'],
  [11, 'Meera J., Pune', 'The headphones I received are the wrong colour. I ordered black, got white. Can I exchange them or should I return for a refund?', 'refund', 'normal'],
  [12, 'Kevin R., Illinois', 'When will the Zen tablet be back in stock? I want to buy it as a gift before the end of next month.', 'sales_question', 'normal'],
  [13, 'Arjun T., Kochi', "My order was supposed to arrive yesterday for my sister's wedding today. Tracking hasn't moved from the Kochi hub for 2 days. Please help, I need it by this evening.", 'order_status', 'high'],
  [14, 'Sarah M., Washington', 'The fitness band screen has a dead line of pixels down the middle. It arrived like this, never dropped it.', 'damaged_item', 'normal'],
  [15, 'Nikhil B., Jaipur', "The VoltKart app keeps crashing when I try to apply a coupon at checkout. I'm on Android 15. Can you fix it so I can complete my order?", 'technical_help', 'normal'],
  [16, 'Olivia G., Georgia', 'I cancelled my order within 10 minutes but I was still charged $189. The order shows cancelled. When do I get my money back?', 'refund', 'normal'],
  [17, 'Rohan D., Kolkata', 'Is there an EMI option for the 65-inch OLED TV with HDFC credit cards? And is installation included?', 'sales_question', 'normal'],
  [18, 'Michael B., Arizona', "Package says out for delivery since 8 am, it's now 9 pm. Is it still coming today? Order VK-US-30914.", 'order_status', 'normal'],
  [19, 'Divya P., Ahmedabad', "The camera lens I received has a scratch inside the glass and the box seal was already broken. Looks used. I'm very unhappy.", 'damaged_item', 'normal'],
  [20, 'Chris H., Colorado', "My smart thermostat stopped working and the house is freezing, it's -5 outside. The display is blank even after changing batteries. Need help now.", 'technical_help', 'high'],
];
EMAILS.forEach(([n, from, text, cat, urg]) => cases.push({ chapter: '4', case_id: 'E' + n, prompt: RULE + '\n\nEmail from ' + from + ':\n' + text, expect: { category: cat, urgency: urg } }));
const out = [];
cases.filter(c => CHAPTERS.includes(c.chapter)).forEach(c => MODELS.forEach(m => {
  const max = c.chapter === '2' ? 12000 : 6000;   // chapter 2 answers are long (thinking counts toward the cap)
  const body = c.image ? null   // chapter 3: 'Attach Image' builds the body after the download
    : m.provider === 'openai'
    ? { model: m.id, input: c.prompt, reasoning: { effort: 'medium' }, max_output_tokens: max }
    : { contents: [{ role: 'user', parts: [{ text: c.prompt }] }], generationConfig: { thinkingConfig: { thinkingLevel: 'medium' }, maxOutputTokens: max } };
  out.push({ json: { run: RUN, ...c, model: m.id, provider: m.provider, label: m.label, prices: { now: [m.price_in, m.price_out], dec: [m.price_in_dec, m.price_out_dec] }, body: body ? JSON.stringify(body) : '', max } });
}));
return out;

// ===== Model Bench · Attach Image (chapter 3): puts the downloaded invoice into the request, the same image and words for both models =====
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const it = $input.all()[i]; const c = $('Test Cases').itemMatching(i).json;
  const bin = (it.binary || {}).data; if (!bin) throw new Error('No image downloaded for ' + c.case_id + ' (' + c.image + ')');
  const b64 = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('base64'); const mime = bin.mimeType || 'image/jpeg';
  const body = c.provider === 'openai'
    ? { model: c.model, input: [{ role: 'user', content: [{ type: 'input_text', text: c.prompt }, { type: 'input_image', image_url: 'data:' + mime + ';base64,' + b64 }] }], reasoning: { effort: 'medium' }, max_output_tokens: c.max || 6000 }
    : { contents: [{ role: 'user', parts: [{ text: c.prompt }, { inline_data: { mime_type: mime, data: b64 } }] }], generationConfig: { thinkingConfig: { thinkingLevel: 'medium' }, maxOutputTokens: c.max || 6000 } };
  out.push({ json: { ...c, drive_file: { id: it.json.id || '', name: it.json.name || c.image }, body: JSON.stringify(body) } });
}
if (out.length !== $('Test Cases').all().length) throw new Error('Found ' + out.length + ' images for ' + $('Test Cases').all().length + ' test items: check the file names in Drive');
return out;

// ===== Model Bench · Measure: time, text, tokens (thinking included), cost now and from 1 Dec; any error is kept for the issues log =====
const c = $('Stamp').first().json; const r = $input.first().json || {}; const ms = Date.now() - c.t0;
let text = '', tin = 0, tout = 0, think = 0, err = '';
if (c.provider === 'openai') {
  (r.output || []).forEach(o => { if (o.type === 'message') (o.content || []).forEach(x => { if (x.type === 'output_text') text += x.text; }); });
  const u = r.usage || {}; tin = u.input_tokens || 0; tout = u.output_tokens || 0; think = (u.output_tokens_details || {}).reasoning_tokens || 0;
  if (r.error) err = String(r.error.message || JSON.stringify(r.error)).slice(0, 300);
  if (!err && r.status && r.status !== 'completed') err = 'status ' + r.status + (r.incomplete_details ? ': ' + JSON.stringify(r.incomplete_details) : '');
} else {
  const p = (((r.candidates || [])[0] || {}).content || {}).parts || []; text = p.filter(x => !x.thought && x.text).map(x => x.text).join('');
  const u = r.usageMetadata || {}; tin = u.promptTokenCount || 0; think = u.thoughtsTokenCount || 0; tout = (u.candidatesTokenCount || 0) + think;
  if (r.error) err = String(r.error.message || JSON.stringify(r.error)).slice(0, 300);
  const fr = ((r.candidates || [])[0] || {}).finishReason; if (!err && fr && fr !== 'STOP') err = 'finishReason ' + fr;
}
if (!err && !text) err = 'empty answer';
const cost = p => Math.round((tin * p[0] + tout * p[1]) / 1e6 * 1e6) / 1e6;
return [{ json: { run: c.run, chapter: c.chapter, case_id: c.case_id, model: c.model, label: c.label, prompt: c.prompt, expect: c.expect, ms, text, tokens_in: tin, tokens_out: tout, tokens_thinking: think,
  cost_now: cost(c.prices.now), cost_dec: cost(c.prices.dec), error: err } }];

// ===== Model Bench · Score: code checks where there is a right answer (chapters 3 and 4), totals per model; the full log is attached as results.json (open this node's output > Binary > Download) =====
const rows = $input.all().map(i => i.json).filter(r => r.case_id);
const strictJson = t => { const s = String(t || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim(); try { return { ok: true, v: JSON.parse(s) }; } catch (e) { return { ok: false, v: null }; } };
rows.forEach(r => { if (r.chapter === '4') { const j = strictJson(r.text); r.json_valid = j.ok; const v = j.v || {};
  r.got = { category: String(v.category || '').trim().toLowerCase(), urgency: String(v.urgency || '').trim().toLowerCase() };
  r.category_ok = !!r.expect && r.got.category === r.expect.category; r.urgency_ok = !!r.expect && r.got.urgency === r.expect.urgency; } });
// chapter 3: each of the 8 fields compared with the answer key (rules fixed before the test: names may add a city after the key; numbers within 0.01;
// dates as ISO or exactly as printed on the invoice, since the prompt asked for no format; currency symbols map to codes)
const nz = v => String(v == null ? '' : v).toLowerCase().replace(/[^a-z0-9]/g, '');
const num = v => { if (v == null || v === '') return null; const n = parseFloat(String(v).replace(/[^0-9.\-]/g, '')); return isFinite(n) ? n : null; };
const cur = v => { const s = String(v || '').trim().toLowerCase(); return /inr|₹|rs/.test(s) ? 'INR' : /usd|\$/.test(s) ? 'USD' : s.toUpperCase(); };
const F3 = ['invoice_number', 'invoice_date', 'supplier_name', 'customer_name', 'subtotal', 'tax', 'total', 'currency'];
const ok3 = (f, got, k) => {
  if (['subtotal', 'tax', 'total'].includes(f)) { const g = num(got); return g != null && Math.abs(g - k[f]) < 0.011; }
  if (f === 'currency') return cur(got) === k.currency;
  if (f === 'invoice_date') return String(got || '').trim() === k.invoice_date || String(got || '').trim() === k.printed_date;
  if (f === 'invoice_number') return nz(got) === nz(k.invoice_number);
  return nz(got) !== '' && nz(got).startsWith(nz(k[f]));
};
rows.forEach(r => { if (r.chapter === '3' && r.expect) { const j = strictJson(r.text); r.json_valid = j.ok; const v = j.v || {};
  r.fields = F3.map(f => ({ field: f, got: v[f] === undefined ? null : v[f], expected: f === 'invoice_date' ? r.expect.invoice_date + ' (or ' + r.expect.printed_date + ')' : r.expect[f], ok: j.ok && ok3(f, v[f], r.expect) }));
  r.fields_ok = r.fields.filter(x => x.ok).length; } });
const models = [...new Set(rows.map(r => r.model))];
const summary = models.map(m => { const R = rows.filter(r => r.model === m); const ch = k => R.filter(r => r.chapter === k); const avg = a => a.length ? Math.round(a.reduce((x, y) => x + y, 0) / a.length) : 0;
  const c4 = ch('4');
  return { model: m, label: (R[0] || {}).label, answers: R.length, errors: R.filter(r => r.error).length,
    avg_seconds: avg(R.map(r => r.ms)) / 1000, avg_tokens_out: avg(R.map(r => r.tokens_out)), avg_tokens_thinking: avg(R.map(r => r.tokens_thinking)),
    cost_now: Math.round(R.reduce((a, r) => a + r.cost_now, 0) * 10000) / 10000, cost_dec: Math.round(R.reduce((a, r) => a + r.cost_dec, 0) * 10000) / 10000,
    ch3: ch('3').length ? { cases: ch('3').length, fields_ok: ch('3').reduce((a, r) => a + (r.fields_ok || 0), 0), fields_total: ch('3').length * 8, json_valid: ch('3').filter(r => r.json_valid).length, misses: ch('3').flatMap(r => (r.fields || []).filter(x => !x.ok).map(x => r.case_id + ' ' + x.field + ': got ' + JSON.stringify(x.got))) } : null,
    ch4: c4.length ? { cases: c4.length, category_ok: c4.filter(r => r.category_ok).length, urgency_ok: c4.filter(r => r.urgency_ok).length, json_valid: c4.filter(r => r.json_valid).length,
      avg_seconds: avg(c4.map(r => r.ms)) / 1000, cost_per_1000_now: Math.round(c4.reduce((a, r) => a + r.cost_now, 0) / c4.length * 1000 * 100) / 100, cost_per_1000_dec: Math.round(c4.reduce((a, r) => a + r.cost_dec, 0) / c4.length * 1000 * 100) / 100 } : null }; });
const run = (rows[0] || {}).run || 'bench';
const doc = { run, made: $now.toISO(), settings: 'reasoning medium on both; one run per case; prompts identical', summary, rows };
return [{ json: { key: 'assets/bench/' + run + '/results.json', run, summary }, binary: { data: await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(doc, null, 1)), 'results.json', 'application/json') } }];
